extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return

	var save_manager: Node = main.get_node_or_null("/root/SaveManager")
	if not check("sm_exists", save_manager != null, "L'Autoload SaveManager deve essere presente nell'albero dei nodi"):
		return

	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena serve il nodo Player (CharacterBody2D)"):
		return

	var door := find_by_name(main, "Door")
	if not check("door", door != null, "Nella scena deve esserci un nodo Door"):
		return

	player.global_position = Vector2(320.0, 180.0)
	player.set("keys", 4)
	call_if_exists(door, "open")
	await wait_frames(2)

	call_if_exists(save_manager, "save_game", [player, main])
	await wait_frames(2)

	# Modifichiamo lo stato per verificare se load_game ripristina davvero i dati
	player.global_position = Vector2(0.0, 0.0)
	player.set("keys", 0)
	call_if_exists(door, "close")
	await wait_frames(2)

	call_if_exists(save_manager, "load_game", [player, main])
	await wait_frames(2)

	var dist: float = player.global_position.distance_to(Vector2(320.0, 180.0))
	check("pos_restored", dist < 2.0, "Dopo il caricamento il giocatore deve tornare alla posizione salvata (distanza: %.1f)" % dist)
	var keys_loaded: int = int(player.get("keys"))
	check("keys_restored", keys_loaded == 4, "Le chiavi del giocatore devono essere 4 (trovate: %d)" % keys_loaded)
	var is_open_val: bool = bool(get_prop(door, "is_open", false))
	check("door_restored", is_open_val == true, "La porta deve tornare aperta dopo aver caricato il salvataggio")

