signal opened
signal closed

@export var requires_key: bool = false
@export var is_open: bool = false

@onready var collision_shape: CollisionShape2D = $CollisionShape2D
@onready var interaction_area: Area2D = $InteractionArea

var current_player: CharacterBody2D = null
var _frame_count: int = 0
var _last_interact_frame: int = -1


func _ready() -> void:
	interaction_area.body_entered.connect(_on_interaction_body_entered)
	interaction_area.body_exited.connect(_on_interaction_body_exited)
	_update_appearance()


func _process(_delta: float) -> void:
	_frame_count += 1
	if Input.is_action_just_pressed("interact"):
		_try_interact()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("interact"):
		_try_interact()


func _try_interact() -> void:
	if _last_interact_frame == _frame_count:
		return
	_last_interact_frame = _frame_count

	if is_open:
		return

	var p: CharacterBody2D = _get_interacting_player()
	if p != null:
		if requires_key:
			var player_keys: int = int(p.get("keys"))
			if player_keys > 0:
				p.set("keys", player_keys - 1)
				open()
		else:
			open()


func _get_interacting_player() -> CharacterBody2D:
	if current_player != null:
		return current_player
	for body in interaction_area.get_overlapping_bodies():
		if body.name == "Player" and body is CharacterBody2D:
			return body as CharacterBody2D
	var current_scene := get_tree().current_scene
	if current_scene != null:
		var scene_player: Node = current_scene.find_child("Player", true, false)
		if scene_player != null and scene_player is CharacterBody2D:
			var cb := scene_player as CharacterBody2D
		if global_position.distance_to(cb.global_position) < 60.0:
			return cb
	return null


func open() -> void:
	if is_open:
		return
	is_open = true
	collision_shape.set_deferred("disabled", true)
	_update_appearance()
	opened.emit()


func close() -> void:
	if not is_open:
		return
	is_open = false
	collision_shape.set_deferred("disabled", false)
	_update_appearance()
	closed.emit()


func _update_appearance() -> void:
	if is_open:
		modulate.a = 0.3
	else:
		modulate.a = 1.0


func _on_interaction_body_entered(body: Node2D) -> void:
	if body.name == "Player" and body is CharacterBody2D:
		current_player = body as CharacterBody2D


func _on_interaction_body_exited(body: Node2D) -> void:
	if body == current_player:
		current_player = null


func get_save_data() -> Dictionary:
	return {
		"is_open": is_open
	}


func load_save_data(data: Dictionary) -> void:
	if data.get("is_open", false):
		open()
	else:
		close()

